-- RTF-038 reconciliation distributed claim columns
ALTER TABLE cpf_unknown_result ADD (
    attempt_count NUMBER(10) DEFAULT 0 NOT NULL,
    next_check_at TIMESTAMP(3) NULL,
    lease_owner VARCHAR2(120 CHAR) NULL,
    lease_until TIMESTAMP(3) NULL,
    row_version NUMBER(19) DEFAULT 0 NOT NULL
);
CREATE INDEX ix_cpf_unknown_result_claim ON cpf_unknown_result (unknown_status, next_check_at, lease_until, detected_at);

-- CPF Enterprise QA V64 - Runtime Control Plane (Oracle)
ALTER TABLE cpf_service ADD (row_version NUMBER(19) DEFAULT 0 NOT NULL);
ALTER TABLE cpf_service_endpoint ADD (row_version NUMBER(19) DEFAULT 0 NOT NULL);
ALTER TABLE cpf_service_instance ADD (environment_code VARCHAR2(40) DEFAULT 'default' NOT NULL, zone_code VARCHAR2(60), cell_code VARCHAR2(60), priority_no NUMBER(10) DEFAULT 100 NOT NULL, maintenance_yn CHAR(1) DEFAULT 'N' NOT NULL, drain_yn CHAR(1) DEFAULT 'N' NOT NULL, drain_deadline_at TIMESTAMP(3), row_version NUMBER(19) DEFAULT 0 NOT NULL);
CREATE INDEX ix_cpf_service_instance_placement ON cpf_service_instance(environment_code,zone_code,cell_code,active_yn,instance_status);
CREATE INDEX ix_cpf_service_instance_route ON cpf_service_instance(endpoint_code,priority_no,maintenance_yn,drain_yn,active_yn,instance_status);
ALTER TABLE cpf_service_instance ADD CONSTRAINT ck_cpf_service_instance_maintenance CHECK(maintenance_yn IN ('Y','N'));
ALTER TABLE cpf_service_instance ADD CONSTRAINT ck_cpf_service_instance_drain CHECK(drain_yn IN ('Y','N'));

CREATE TABLE cpf_runtime_version(version_key VARCHAR2(40) PRIMARY KEY,version_no NUMBER(19) DEFAULT 0 NOT NULL,created_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,updated_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
INSERT INTO cpf_runtime_version(version_key,version_no) VALUES('GLOBAL',0);

CREATE TABLE cpf_runtime_controller_lease(lease_key VARCHAR2(60) PRIMARY KEY,holder_id VARCHAR2(120) NOT NULL,fencing_token NUMBER(19) DEFAULT 0 NOT NULL,lease_until TIMESTAMP(3) NOT NULL,last_reconciled_at TIMESTAMP(3),created_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,updated_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX ix_cpf_runtime_controller_lease_until ON cpf_runtime_controller_lease(lease_until);

CREATE TABLE cpf_runtime_rate_bucket(bucket_key VARCHAR2(180) PRIMARY KEY,subject_id VARCHAR2(120) NOT NULL,window_start TIMESTAMP(3) NOT NULL,request_count NUMBER(10) DEFAULT 0 NOT NULL,created_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,updated_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT ck_cpf_runtime_rate_count CHECK(request_count >= 0));
CREATE INDEX ix_cpf_runtime_rate_subject ON cpf_runtime_rate_bucket(subject_id,window_start);


CREATE TABLE cpf_runtime_instance_group(group_id VARCHAR2(80) PRIMARY KEY,group_name VARCHAR2(150) NOT NULL,parent_group_id VARCHAR2(80),environment_code VARCHAR2(40),description VARCHAR2(500),active_yn CHAR(1) DEFAULT 'Y' NOT NULL,row_version NUMBER(19) DEFAULT 0 NOT NULL,created_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,updated_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT fk_cpf_runtime_group_parent FOREIGN KEY(parent_group_id) REFERENCES cpf_runtime_instance_group(group_id),CONSTRAINT ck_cpf_runtime_group_active CHECK(active_yn IN ('Y','N')));
CREATE INDEX ix_cpf_runtime_group_parent ON cpf_runtime_instance_group(parent_group_id,active_yn); CREATE INDEX ix_cpf_runtime_group_env ON cpf_runtime_instance_group(environment_code,active_yn);
CREATE TABLE cpf_runtime_group_member(group_id VARCHAR2(80) NOT NULL,instance_id VARCHAR2(120) NOT NULL,active_yn CHAR(1) DEFAULT 'Y' NOT NULL,created_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,updated_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,PRIMARY KEY(group_id,instance_id),CONSTRAINT fk_cpf_runtime_group_member_group FOREIGN KEY(group_id) REFERENCES cpf_runtime_instance_group(group_id) ON DELETE CASCADE,CONSTRAINT fk_cpf_runtime_group_member_instance FOREIGN KEY(instance_id) REFERENCES cpf_service_instance(instance_id) ON DELETE CASCADE,CONSTRAINT ck_cpf_runtime_group_member_active CHECK(active_yn IN ('Y','N')));
CREATE INDEX ix_cpf_runtime_group_member_instance ON cpf_runtime_group_member(instance_id,active_yn);
CREATE TABLE cpf_runtime_instance_state(instance_id VARCHAR2(120) PRIMARY KEY,fencing_token NUMBER(19) DEFAULT 0 NOT NULL,lease_until TIMESTAMP(3),desired_version NUMBER(19) DEFAULT 0 NOT NULL,actual_version NUMBER(19) DEFAULT 0 NOT NULL,desired_hash VARCHAR2(64),actual_hash VARCHAR2(64),drift_state VARCHAR2(30) DEFAULT 'IN_SYNC' NOT NULL,capabilities_json CLOB,labels_json CLOB,artifact_version VARCHAR2(100),artifact_commit VARCHAR2(64),runtime_role VARCHAR2(40),registration_source VARCHAR2(120),schema_version VARCHAR2(100),config_hash VARCHAR2(64),clock_skew_ms NUMBER(19) DEFAULT 0 NOT NULL,last_ack_change_id VARCHAR2(80),last_ack_at TIMESTAMP(3),heartbeat_at TIMESTAMP(3),created_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,updated_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT fk_cpf_runtime_instance_state_instance FOREIGN KEY(instance_id) REFERENCES cpf_service_instance(instance_id) ON DELETE CASCADE,CONSTRAINT ck_cpf_runtime_instance_drift CHECK(drift_state IN ('IN_SYNC','PENDING','DRIFT','UNKNOWN','UNKNOWN_RESULT','PENDING_RESTART','EXCLUDED')));
CREATE INDEX ix_cpf_runtime_instance_lease ON cpf_runtime_instance_state(lease_until); CREATE INDEX ix_cpf_runtime_instance_drift ON cpf_runtime_instance_state(drift_state,heartbeat_at);

CREATE TABLE cpf_runtime_instance_feature_state(instance_id VARCHAR2(120) NOT NULL,change_type VARCHAR2(80) NOT NULL,desired_version NUMBER(19) DEFAULT 0 NOT NULL,actual_version NUMBER(19) DEFAULT 0 NOT NULL,desired_hash VARCHAR2(64),actual_hash VARCHAR2(64),drift_state VARCHAR2(30) DEFAULT 'UNKNOWN' NOT NULL,source_delivery_id VARCHAR2(80),created_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,updated_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,PRIMARY KEY(instance_id,change_type),CONSTRAINT fk_cpf_runtime_feature_instance FOREIGN KEY(instance_id) REFERENCES cpf_service_instance(instance_id) ON DELETE CASCADE,CONSTRAINT ck_cpf_runtime_feature_drift CHECK(drift_state IN ('IN_SYNC','PENDING','DRIFT','UNKNOWN','UNKNOWN_RESULT','PENDING_RESTART','EXCLUDED')));
CREATE INDEX ix_cpf_runtime_feature_drift ON cpf_runtime_instance_feature_state(drift_state,change_type);
CREATE INDEX ix_cpf_runtime_feature_delivery ON cpf_runtime_instance_feature_state(source_delivery_id);

CREATE TABLE cpf_control_operation(operation_id VARCHAR2(100) PRIMARY KEY,command_type VARCHAR2(80) NOT NULL,request_hash VARCHAR2(64) NOT NULL,entity_id VARCHAR2(100),result_state VARCHAR2(30) DEFAULT 'PROCESSING' NOT NULL,result_json CLOB,expires_at TIMESTAMP(3),created_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,updated_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT ck_cpf_control_operation_state CHECK(result_state IN ('PROCESSING','SUCCESS','FAILED','UNKNOWN','EXPIRED','CANCELLED')));
CREATE INDEX ix_cpf_control_operation_expiry ON cpf_control_operation(result_state,expires_at);
CREATE TABLE cpf_runtime_change(change_id VARCHAR2(80) PRIMARY KEY,operation_id VARCHAR2(100) NOT NULL UNIQUE,change_type VARCHAR2(80) NOT NULL,payload_schema_version NUMBER(10) DEFAULT 1 NOT NULL,request_hash VARCHAR2(64) NOT NULL,payload_hash VARCHAR2(64) NOT NULL,payload_json CLOB NOT NULL,rollback_payload_json CLOB,target_snapshot_json CLOB NOT NULL,desired_version NUMBER(19) NOT NULL,rollout_mode VARCHAR2(30) DEFAULT 'ALL_AT_ONCE' NOT NULL,wave_size NUMBER(10) DEFAULT 100 NOT NULL,quorum_percent NUMBER(10) DEFAULT 100 NOT NULL,change_state VARCHAR2(30) DEFAULT 'APPLYING' NOT NULL,scheduled_at TIMESTAMP(3),expires_at TIMESTAMP(3),reason VARCHAR2(1000) NOT NULL,approval_id VARCHAR2(100),break_glass_id VARCHAR2(100),requested_by VARCHAR2(100) NOT NULL,created_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,updated_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT fk_cpf_runtime_change_operation FOREIGN KEY(operation_id) REFERENCES cpf_control_operation(operation_id),CONSTRAINT ck_cpf_runtime_change_state CHECK(change_state IN ('SCHEDULED','APPLYING','PARTIAL','SUCCESS','FAILED','CANCELLED','EXPIRED','ROLLBACK_PENDING','ROLLED_BACK','SUPERSEDED','UNKNOWN_RESULT','RECOVERED')));
CREATE INDEX ix_cpf_runtime_change_state ON cpf_runtime_change(change_state,scheduled_at,expires_at);
CREATE TABLE cpf_runtime_delivery(delivery_id VARCHAR2(80) PRIMARY KEY,change_id VARCHAR2(80) NOT NULL,instance_id VARCHAR2(120) NOT NULL,sequence_no NUMBER(10) NOT NULL,desired_version NUMBER(19) NOT NULL,delivery_state VARCHAR2(30) DEFAULT 'PENDING' NOT NULL,attempt_no NUMBER(10) DEFAULT 0 NOT NULL,next_attempt_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,fencing_token NUMBER(19),claimed_at TIMESTAMP(3),acknowledged_at TIMESTAMP(3),actual_hash VARCHAR2(64),error_code VARCHAR2(80),error_message VARCHAR2(900),created_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,updated_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT fk_cpf_runtime_delivery_change FOREIGN KEY(change_id) REFERENCES cpf_runtime_change(change_id) ON DELETE CASCADE,CONSTRAINT fk_cpf_runtime_delivery_instance FOREIGN KEY(instance_id) REFERENCES cpf_service_instance(instance_id) ON DELETE CASCADE,CONSTRAINT ck_cpf_runtime_delivery_state CHECK(delivery_state IN ('PENDING','CLAIMED','ACKED','FAILED','POISONED','UNKNOWN_RESULT','RESTART_REQUIRED','CANCELLED','EXPIRED','SUPERSEDED')));
CREATE INDEX ix_cpf_runtime_delivery_claim ON cpf_runtime_delivery(instance_id,delivery_state,next_attempt_at,sequence_no); CREATE INDEX ix_cpf_runtime_delivery_change ON cpf_runtime_delivery(change_id,delivery_state);
CREATE TABLE cpf_runtime_change_audit(audit_id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,change_id VARCHAR2(80) NOT NULL,event_type VARCHAR2(60) NOT NULL,actor_id VARCHAR2(100) NOT NULL,reason VARCHAR2(500),evidence_hash VARCHAR2(64),previous_hash VARCHAR2(64) NOT NULL,chain_hash VARCHAR2(64) NOT NULL,created_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT fk_cpf_runtime_audit_change FOREIGN KEY(change_id) REFERENCES cpf_runtime_change(change_id) ON DELETE CASCADE);
CREATE INDEX ix_cpf_runtime_change_audit_change ON cpf_runtime_change_audit(change_id,audit_id);
CREATE TABLE cpf_cache_refresh_checkpoint(consumer_id VARCHAR2(120) PRIMARY KEY,last_event_id NUMBER(19) DEFAULT 0 NOT NULL,last_applied_at TIMESTAMP(3),created_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,updated_by VARCHAR2(100) DEFAULT 'CPF' NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX ix_cpf_cache_refresh_checkpoint_event ON cpf_cache_refresh_checkpoint(last_event_id);
